class NoteStore(BaseStore):
    """Stores notes in memory."""

    def save(self, note):
        if self.size() >= MAX_NOTES:
            raise ValueError("full")
        self.items[note.note_id] = note
        return note

    def load(self, note_id):
        return self.items.get(note_id)
